rss.channel:
    {{ .Title }} -- {{ .Site.Title }}
    {{ .Site.BaseURL }}internet/
    A curated collection of articles about the internet, past and present.
    Hugo -- gohugo.io
    {{ site.LanguageCode }}
    {{ now.Format "Mon, 02 Jan 2006 15:04:05 -0700" }}


    {{ range .Pages }}
      {{- $authors := slice -}}
      {{- range .Params.authors -}}
        {{- if .url -}}
          {{- $authors = $authors | append (printf "%s" .url .name) -}}
        {{- else -}}
          {{- $authors = $authors | append .name -}}
        {{- end -}}
      {{- end -}}

      {{- $authorStr := "" -}}
      {{- if $authors -}}
        {{- $authorStr = printf "
By %s" (delimit $authors ", ") -}}
      {{- end -}}

      {{- $pubDate := "" -}}
      {{- with .Params.datePublished -}}
        {{- $pubDate = printf "
Originally published %s" (dateFormat "2 Jan 2006" .) -}}
      {{- end -}}

      {{- $itemLink := .Params.link | default .Permalink -}}



        {{ .Title }}
        {{ $itemLink }}
        {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" }}
        {{ .Params.link }}

          {{- printf "%s%s
Added to this site %s
Read the article →" $authorStr $pubDate (.Date.Format "2 Jan 2006") .Params.link | safeHTML -}}


    {{ end }}
